styleCss:
:root, html, body{
    overscroll-behavior: none;
}
body{
    min-width: 980px;
font-family:"Roboto";
}

.card {
border: none !important;
}

.research-header-menu-wrapper {
    background-color: white;
    display: flex;
    align-items: flex-end;
    justify-content: space-between;
    box-shadow: 0 0px 2px 0px #f2682250;
    z-index: 1;
}
.rp-header-logo p {
    margin: 0 !important;
}
.rp-header-logo img {
    height: 40px;
}
.rp-header-logo span {
    display: inline-block;
    color: white;
    background: #ccc;
    height: 100%;
    width: 1px;
    margin: 0 5px;
}
.paper-footer-wrapper {
    background-color: white;
    box-shadow: 0 0px 2px 0px #f2682250;
    z-index: 1;
}
.research-header-menu-wrapper ul li.menu a {
    color: #1c5084 !important;
    font-weight: bold;
    font-size: 14px;
   position: relative;
}
.research-header-menu-wrapper ul li.menu a:hover {
    color: #1c5084 !important;
    text-decoration: none;
}
.research-header-menu-wrapper ul li.menu a:after {
    content: '';
    background: #f26822;
    width: 0%;
    height: 2px;
    position: absolute;
    left: 50%;
    transform: translateX(-50%);
    bottom: -5px;
    transition: width .2s;
}
.research-header-menu-wrapper ul li.menu a:hover:after {
    width: 70%;
}
